import type { Lane } from '../config/schema.js'

export interface GateProfile {
  runLint: boolean
  runTypecheck: boolean
  runTest: boolean
  runIntegrationTest: boolean
}

const GATE_PROFILES: Record<Lane, GateProfile> = {
  docs: {
    runLint: true,
    runTypecheck: false,
    runTest: false,
    runIntegrationTest: false,
  },
  tests: {
    runLint: true,
    runTypecheck: true,
    runTest: true,
    runIntegrationTest: false,
  },
  simple_bugs: {
    runLint: true,
    runTypecheck: true,
    runTest: true,
    runIntegrationTest: false,
  },
  experimental: {
    runLint: true,
    runTypecheck: true,
    runTest: true,
    runIntegrationTest: true,
  },
}

export function getGateProfile(lane: Lane): GateProfile {
  return GATE_PROFILES[lane]
}
